    memo = {}

    def grundy(x):
        if x == 0:
            return 0
        if x in memo:
            return memo[x]

        reachable = set()
        reachable.add(grundy(x - 1))

        if x % 2 == 0:
            half = x // 2
            if k % 2 == 0:
                reachable.add(0)
            else:
                reachable.add(grundy(half))

        g = 0
        while g in reachable:
            g += 1

        memo[x] = g
        return g

