def solution(input_data):
    lines = input_data.strip().split('\n')
    if len(lines) == 0:
        return "0\n\n"

    n, m, k = map(int, lines[0].split())

    # Handle the case with 1 node
    if n == 1:
        return "0\n\n"

    # Store edges with their original indices (1-indexed)
    edges = []
    capital_edges = []  # Edges connected to node 1
    regular_edges = []  # Edges not connected to node 1

    for i in range(1, m + 1):
        if len(lines) < i:
            break
        parts = lines[i].split()
        a, b, w = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((a, b, w, i))
        if a == 1 or b == 1:
            capital_edges.append((a, b, w, i))
        else:
            regular_edges.append((a, b, w, i))

    # Sort edges by weight
    capital_edges.sort(key=lambda x: x[2])
    regular_edges.sort(key=lambda x: x[2])

    # Check if we have enough capital edges
    if len(capital_edges) < k:
        return "-1" + "\n"

    # We need exactly k edges connected to node 1
    # Strategy: We select k capital edges (prefer smaller ones) and fill remaining tree with regular edges
    # But we need to make sure all nodes get connected

    parent = list(range(n + 1))
    result_edges = []

    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j, cost):
        rootI = find(i)
        rootJ = find(j)
        if rootI != rootJ:
            parent[rootJ] = rootI
            return True, rootI
        return False, rootI

    # First pass: Select k capital edges
    capital_used = 0
    # We need to connect different components using capital edges
    # Strategic approach: Only use capital edges that help connectivity to new nodes
    capital_indices = set()

    for i, (a, b, w, idx) in enumerate(capital_edges):
        if capital_used >= k:
            break
        if b == 1:
            used, root = union(a, b, w)
            if used:
                capital_indices.add(idx)
                capital_used += 1
                result_edges.append(idx)

    # Ensure we connect node 1 to exactly k distinct nodes via capital roads
    # Track which nodes are connected to node 1
    connected_to_capital = {1}
    capital_selected = []

    for i, (a, b, w, idx) in capital_edges[:k]:
        # We want exactly k edges connected to node 1
        # Capital road means either endpoint is node 1
        if used, root := union(a, b, w):
            capital_selected.append(idx)
            if b == 1 and a not in connected_to_capital:
                connected_to_capital.add(a)
            else:
                connected_to_capital.add(b)

    # Use regular edges to complete the spanning tree
    for _, a, b, idx in regular_edges:
        used, _ = union(a, b, 0)
        if used:
            result_edges.append(idx)

    # Check if all nodes are connected (final check: find should return same root for all)
    root_check = find(1)
    for i in range(2, n + 1):
        if find(i) != root_check:
            return "-1" + "\n"

    # Verify we have exactly k capital edges
    capital_count = 0
    component_info = {}
    for idx in result_edges:
        for i, (a, b, w, orig_idx) in enumerate(capital_edges):
            if orig_idx == idx:
                capital_count += 1
                break

    if capital_count != k:
        return "-1" + "\n"

    # Output result
    n_edges = len(result_edges)
    edge_indices = sorted(result_edges)
    return f"{n_edges}\n" + " ".join(map(str, edge_indices)) + "\n"

