    """Computes sum of digit sums for i from 0 to n"""
    if n < 0:
        return 0
    if n == 0:
        return 0

    s = str(n)
    n_digits = len(s)

    # dp returns (count, digit_sum) for remaining suffix
    memo = {}

    def dp(pos, tight, leading_zeros):
        if pos == n_digits:
            return (1, 0)  # 1 number (empty), digit sum 0

        state = (pos, tight, leading_zeros)
        if state in memo:
            return memo[state]

        limit = int(s[pos]) if tight else 9
        total_count = 0
        total_sum = 0

        for digit in range(10):
            new_tight = tight and (digit == limit)
            new_leading_zeros = leading_zeros and (digit == 0)

            if new_leading_zeros:
                # Not actually contributing to digit sum yet
                cnt, ss = dp(pos + 1, new_tight, True)
                if cnt > 0:
                    total_count += cnt
                    # Leading zeros don't contribute to actual digit sum
                    total_sum += ss
            else:
                # Digit contributes to sum
                cnt, ss = dp(pos + 1, new_tight, False)
                if cnt > 0:
                    total_count += cnt
                    total_sum += digit * cnt + ss

        memo[state] = (total_count, total_sum)
        return memo[state]

    _, result = dp(0, True, True)
    return result


