        position = k

        while left <= right:
            mid = (left + right) // 2
            if mid < 1 or cum_block_len(mid) < k:
                left = mid + 1
            elif cum_block_len(mid) >= k:
                best = mid
                position = k - cum_block_len(best - 1)
                right = mid - 1

        block = best
        pos_in_block = position

        # Find which number in the block (1 to block)
        num = 1
        digits_found = 0

        while True:
            num_len = len(str(num))
            if digits_found + num_len >= pos_in_block:
                digit_idx = pos_in_block - digits_found - 1
                return str(num)[digit_idx]
            digits_found += num_len
            num += 1

    results = []
    for k in k_list:
        digit = find_kth_digit(k)
        results.append(digit)

    return '\n'.join(results)

