def solution(input_str):
    n = int(input_str.split('\n')[0])
    matrix = []
    lines = input_str.strip().split('\n')[1:]
    for line in lines:
        matrix.append(list(map(int, line.split())))

    # Precompute factors of 2 and 5 for each cell
    cnt2 = [[0] * n for _ in range(n)]
    cnt5 = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            val = matrix[i][j]
            while val % 2 == 0 and val > 0:
                cnt2[i][j] += 1
                val //= 2
            x = val
            while x % 5 == 0 and x > 0:
                cnt5[i][j] += 1
                x //= 5

    # DP: dp[i][j] = list of (c2, c5, prev_i, prev_j)
    # Represents nondominated (c2, c5) pairs with predecessor info
    dp = [[None] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                dp[i][j] = [(cnt2[0][0], cnt5[0][0], -1, -1)]
            else:
                candidates = []
                if i > 0 and dp[i - 1][j]:
                    for c2, c5, _, _ in dp[i - 1][j]:
                        candidates.append((c2 + cnt2[i][j], c5 + cnt5[i][j], i - 1, j))
                if j > 0 and dp[i][j - 1]:
                    for c2, c5, _, _ in dp[i][j - 1]:
                        candidates.append((c2 + cnt2[i][j], c5 + cnt5[i][j], i, j - 1))

                # Filter and remove dominated entries
                # Sort by c2 ascending, then c5 ascending
                candidates.sort()
                frontier = []
                seen = {}
                for c2, c5, pi, pj in candidates:
                    if (c2, c5) not in seen:
                        seen[(c2, c5)] = True
                        if not frontier or c5 < frontier[-1][1]:
                            frontier.append((c2, c5, pi, pj))

                dp[i][j] = frontier

    # Find best result at (n-1, n-1)
    if n == 0:
        return "0\n"

    cell = dp[n - 1][n - 1]
    best = None
    for c2, c5, pi, pj in cell:
        zeros = min(c2, c5)
        if best is None or zeros < best[0]:
            best = (zeros, c2, c5, pi, pj)

    # Reconstruct path
    path = []
    ci, cj = -1, -1
    for c2, c5, pi, pj in dp[n - 1][n - 1]:
        if c2 == best[1] and c5 == best[2] and (ci, cj) == (pi, pj):
            ci, cj = pi, pj
            break

    while pi != -1 and pj != -1:
        direction = 'D' if ci > 0 else 'R'
        path.append(direction)
        if ci == 0 and pj == 0:
            break
        ci, cj = pi, pj
        path.append('move')

    # Actually reconstruct more carefully
    path_recon = []
    curr_i, curr_j = n - 1, n - 1
    while not (curr_i == 0 and curr_j == 0):
        direction = 'D' if curr_i > 0 else 'R'
        path_recon.append(direction)
        # Find which entry we came from
        best_entry = None
        min_val = 10**20
        if curr_i > 0:
            for e in dp[curr_i - 1][curr_j]:
                if e[0] + cnt2[curr_i][curr_j] == dp[curr_i][curr_j][0][0]:
                    best_val = e[0] + cnt2[curr_i][curr_j]
                    min_val = best_val
        if curr_j > 0:
            for e in dp[curr_i][curr_j - 1]:
                if e[0] + cnt2[curr_i][curr_j] == dp[curr_i][curr_j][0][0]:
                    min_val = dp[curr_i][curr_j][0][0]
        curr_i, curr_j = 0, 0

    # Better reconstruction
    path_recon = []
    curr_i, curr_j = n - 1, n - 1
    while not (curr_i == 0 and curr_j == 0):
        direction = 'D' if curr_i > 0 else 'R'
        path_recon.append(direction)
        # Backtrack by finding which cell leads to optimal
        # Try both directions to find which could reach current cell with valid counts
        if curr_i > 0:
            has_path = False
            for c2, c5, pi, pj in dp[curr_i - 1][curr_j]:
                if c2 + cnt2[curr_i][curr_j] == dp[curr_i][curr_j][0][0] and \
                   c5 + cnt5[curr_i][curr_j] == dp[curr_i][curr_j][0][1]:
                    curr_i -= 1
                    has_path = True
                    break
            if not has_path:
                curr_j -= 1
        else:
            curr_j -= 1

    path_recon.reverse()

    return f"{best[0]}\n{''.join(path_recon)}"

from collections import defaultdict, deque

def solution(input_str):
    if not input_str or not input_str.strip():
        return "NO"

    # Parse input
    data = input_str.strip().split()
    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    adj = defaultdict(list)
    for _ in range(m):
        a = int(data[idx]); idx += 1
        b = int(data[idx]); idx += 1
        c = int(data[idx]); idx += 1
        adj[a].append((b, c))
        adj[b].append((a, c))

    visited = [False] * (n + 1)
    final_ans = {}

    for start in range(1, n + 1):
        if visited[start]:
            continue

        # BFS for each component
        q = deque([start])
        visited[start] = True
        node_offset = {start: 0}
        t_constraints = []
        active_nodes = set()
        active_nodes.add(start)

        while q:
            u = q.popleft()

            for v, c in adj[u]:
                if v not in visited:
                    visited[v] = True
                    node_offset[v] = c - node_offset[u]
                    active_nodes.add(v)
                    q.append(v)
                else:
                    # Back-edge: check if consistent with current offsets
                    # equation: x[u] + x[v] = c
                    # substituted: (off[u] + t) + (off[v] + t) = c
                    # so: 2t + off[u] + off[v] = c
                    t_val = c - node_offset[u] - node_offset[v]
                    t_constraints.append(t_val)

        # Check consistency - all t constraints must agree
        if t_constraints:
            # All should be equal (they're all values of 2t)
            expected_2t = t_constraints[0]
            for val in t_constraints[1:]:
                if abs(val - expected_2t) > 1e-6:
                    return "NO"
        else:
            expected_2t = 0

        t = expected_2t / 2

        # Compute final values: x[i] = offset[i] + t
        for node in active_nodes:
            final_ans[node] = node_offset[node] + t

    # Verify all edges
    for u in range(1, n + 1):
        for v, c in adj[u]:
            if v > u and u in final_ans and v in final_ans:
                if abs(final_ans[u] + final_ans[v] - c) > 1e-6:
                    return "NO"

    # Output format
    res = []
    for i in range(1, n + 1):
        res.append(f"{final_ans[i]:.6f}")

    return "YES\n" + " ".join(res)

