    n = int(lines[0])
    t = lines[1]

    if n <= 4:
        return str(n)

    # Count maximum number of consecutive identical characters in t
    max_consecutive = 0
    current_consecutive = 0
    prev_char = None

    for c in t:
        if c == prev_char:
            current_consecutive += 1
        else:
            current_consecutive = 1
            prev_char = c
        if current_consecutive > max_consecutive:
            max_consecutive = current_consecutive

    k = max_consecutive
    if k <= 0:
        k = 1

    # Formula: ceil(n/k) + k - 1 = (n + k - 1) // k + k - 1
    answer = (n + k - 1) // k + k - 1

    return str(answer)

