    swapLR = int(swap_lines[0]) if len(swap_lines) > 0 else 0
    swapUD = int(swap_lines[1]) if len(swap_lines) > 1 else 0

    # Parse grid
    grid = []
    line_idx = 2 if len(lines) > 2 else 1
    for i in range(n):
        if line_idx + i < len(lines):
            grid.append(lines[line_idx + i])

    # Find finish position
    finish_pos = None
    for r in range(n):
        for c in range(m):
            if r < len(grid) and c < len(grid[r]) and grid[r][c] == 'F':
                finish_pos = (r, c)
                break
        if finish_pos:
            break

    if not finish_pos:
        return ""

    actual_dr = {'U': -1, 'D': 1}
    actual_dc = {'L': -1, 'R': 1}

    print(f"DEBUG: swapLR={swapLR}, swapUD={swapUD}")
    print(f"DEBUG: finish_pos={finish_pos}")
    print(f"DEBUG: n={n}, m={m}")

    # BFS to find shortest path
    start_pos = (0, 0)
    queue = deque([(start_pos, [])])
    visited = {start_pos}

    while queue:
        (r, c), path = queue.popleft()

        if (r, c) == finish_pos:
            result = '\n'.join(path) + '\n'
            print(f"DEBUG: Found path with {len(path)} moves: {result}")
