def solve_logic(input_str):
    lines = input_str.strip().split('\n')

    try:
        n = int(lines[0])
        points = []
        for i in range(n + 1):
            parts = lines[1 + i].split()
            points.append((int(parts[0]), int(parts[1]), int(parts[2])))

        vp, vs = map(float, lines[2 + n].split())
        Px, Py, Pz = map(float, lines[3 + n].split())
        H = (Px, Py, Pz)
    except (IndexError, ValueError):
        return "NO\n"

    min_t = float('inf')
    best_pos = None

    for i in range(n):
        A = points[i]
        B = points[i+1]
        seg_len = dist(A, B)
        T_seg = seg_len / vs  # Time to traverse segment

        if T_seg == 0 or seg_len == 0:
            continue

        def snitch_at_time(t):
            """Get Snitch position at time t, assuming it's on this segment"""
            if t <= 0:
                return list(A)
            if t >= T_seg:
                return list(B)
            ratio = (t / T_seg)
            return [A[0] + ratio * (B[0] - A[0]),
                    A[1] + ratio * (B[1] - A[1]),
                    A[2] + ratio * (B[2] - A[2])]

        def hp_can_reach_at(t):
            """Check if Harry can reach Snitch position at time t"""
            if t <= 0:
                return dist(H, tuple(A)) <= 0
            dist_to_sp = dist(H, tuple(snitch_at_time(t)))
            return dist_to_sp <= vp * t

        # Binary search for earliest catch time
        low, high = 0.0, T_seg
        found_t = None

        # First check endpoints
        if dist(H, tuple(A)) == 0:
            found_t = 0.0
        elif snapcheck := dist(H, tuple(A)) - vp * 0 == 0:
            found_t = 0.0
        else:
            for _ in range(100):
                mid = (low + high) / 2
                if hp_can_reach_at(mid):
                    found_t = mid
                    high = mid
                else:
                    low = mid

        if found_t is not None and dist(H, tuple(snitch_at_time(found_t))) <= vp * found_t + 1e-9:
            if found_t < min_t:
                min_t = found_t
                best_pos = list(snitch_at_time(found_t))

    if best_pos:
        return f"YES\n{min_t:.10f}\n{best_pos[0]:.10f}\n{best_pos[1]:.10f}\n{best_pos[2]:.10f}\n"
    else:
        # Check start point directly
        if dist(H, points[0]) <= 1e-9:
            return f"YES\n0.000000000000000\n{points[0][0]:.10f}\n{points[0][1]:.10f}\n{points[0][2]:.10f}\n"
        return "NO\n"

