# Your solution code here
def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    s = []
    c = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        s.append(parts[0])
        c.append(int(parts[1]))

    n_left = n // 2
    n_right = n - n_left

    def get_matches(pattern, strings, str_prefix_len):
        """
        Returns list of match counts for this pattern 
        against each string, considering only the appropriate positions
        """
        matches = []
        for s_pat in strings:
            if str_prefix_len is not None:
                s_start = 0
                s_str = s_pat[:str_prefix_len]
            else:
                s_start = 0
                s_str = s_pat
            ms = 0
            n_len = len(s_str)
            for j in range(n_len):
                if ((pattern >> (n_len - 1 - j)) & 1) == int(s_str[j]):
                    ms += 1
            matches.append(ms)
        return matches

    # Precompute match vectors for all left half patterns
    left_vectors = {}

    for l in range(1 << n_left):
        vec = tuple(get_matches(l, s, None))
        vec = tuple(vec[:n_left])
        if vec not in left_vectors:
            left_vectors[vec] = 0
        left_vectors[vec] += 1

    result = 0

    # Check all right half patterns and find matching left patterns
    for r in range(1 << n_right):
        right_matches = get_matches(r, s, n_left)

        for left_vec in left_vectors:
            match = True
            for i in range(m):
                if left_vec[i] + right_matches[i] != c[i]:
                    match = False
                    break
            if match:
                result += left_vectors[left_vec]

    return str(result)
